from __future__ import annotations
from pathlib import Path
import argparse
ROOT: Path

def fail(msg:str): raise SystemExit("ERROR: "+msg)
def one(src:str,old:str,new:str,label:str)->str:
 n=src.count(old)
 if n!=1: fail(f"{label}: expected one anchor, found {n}")
 return src.replace(old,new,1)
def replace_span(src:str,start_token:str,end_token:str,replacement:str,label:str)->str:
 s=src.find(start_token)
 if s<0: fail(label+": start token missing")
 if src.find(start_token,s+1)>=0: fail(label+": start token not unique")
 e=src.find(end_token,s+len(start_token))
 if e<0: fail(label+": end token missing")
 if src.find(end_token,e+1)>=0: fail(label+": end token not unique")
 return src[:s]+replacement+src[e:]
def edit(rel:str,fn):
 p=ROOT/rel
 if not p.is_file(): fail("missing "+rel)
 b=p.read_text();a=fn(b)
 if a==b: fail(rel+": no change")
 p.write_text(a);print("CHANGED",rel)
def add(rel:str,text:str):
 p=ROOT/rel
 if p.exists(): fail("new file already exists "+rel)
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text);print("ADDED",rel)

GEOMETRY_BRIDGE_CLASS='    /* IRIS_26509_NEAREST_NORMAL_GEOMETRY_BRIDGE_OWNER\n     * One copied NORMAL RAW may survive the capture-time early-close solely as a\n     * geometry bridge for Short-A. It is never inserted into MotionBatch.frames and\n     * never becomes a pixel/RGB contributor. Before Short timestamp identity exists,\n     * newest wins; afterwards the closest timestamp wins deterministically.\n     */\n    public static final class GeometryBridgeSlot {\n        private ImageFrame frame;\n        private boolean sealed = false;\n        public synchronized boolean offerNearest(ImageFrame candidate,long shortTimestampNs) {\n            if (candidate == null) return false;\n            if (sealed || candidate.motionV2FrameRole != ImageFrame.MotionV2FrameRole.NORMAL) {\n                try { candidate.close(); } catch (Throwable ignored) {}\n                return false;\n            }\n            boolean replace = frame == null;\n            if (!replace) {\n                if (shortTimestampNs > 0L) {\n                    long oldDistance = Math.abs(frame.timestamp - shortTimestampNs);\n                    long newDistance = Math.abs(candidate.timestamp - shortTimestampNs);\n                    replace = newDistance < oldDistance\n                            || (newDistance == oldDistance && candidate.timestamp > frame.timestamp);\n                } else {\n                    replace = candidate.timestamp > frame.timestamp;\n                }\n            }\n            if (!replace) {\n                try { candidate.close(); } catch (Throwable ignored) {}\n                return false;\n            }\n            if (frame != null) try { frame.close(); } catch (Throwable ignored) {}\n            frame = candidate;\n            notifyAll();\n            return true;\n        }\n        public synchronized ImageFrame peek() { return frame; }\n        public synchronized boolean hasFrame() { return frame != null; }\n        public synchronized long timestamp() { return frame == null ? 0L : frame.timestamp; }\n        public synchronized void seal() { sealed = true; notifyAll(); }\n        public synchronized boolean isSealed() { return sealed; }\n        public synchronized ImageFrame takeAndSeal() {\n            sealed = true;\n            ImageFrame out = frame;\n            frame = null;\n            return out;\n        }\n        public synchronized void sealAndClose() {\n            sealed = true;\n            if (frame != null) {\n                try { frame.close(); } catch (Throwable ignored) {}\n                frame = null;\n            }\n            notifyAll();\n        }\n    }\n\n'
BRIDGE_CAPTURE_METHODS='    /* IRIS_26509_CAPTURE_SIDE_GEOMETRY_BRIDGE\n     * Preserve a nearer normal-exposure RAW that would otherwise be closed while\n     * the intentional Short/Long requests are in flight. Exact Short and exact Long\n     * ownership are checked earlier in the RAW callback and therefore can never be\n     * reclassified as this bridge. Missing result metadata may be refreshed once at\n     * the immutable processing boundary; final host validation rejects it otherwise.\n     */\n    private boolean stageMotion26509NormalGeometryBridge(\n            Motion26486ShortTicket ticket, Image img) {\n        if (ticket == null || img == null || !ticket.requested\n                || ticket.slot == null || ticket.slot.geometryBridgeSlot.isSealed()\n                || ticket.iris26509GenerationId != mMotionUnifiedGeneration) return false;\n        final long ts = img.getTimestamp();\n        final long shortTimestamp = ticket.expectedTimestampNs();\n        /* IRIS_26509_BRIDGE_COPY_ONLY_IF_TIMESTAMP_CLOSER\n         * Do not full-RAW-copy speculative normals before Camera2 has given the\n         * exact Short timestamp. Once known, copy only a candidate that is closer\n         * than the currently owned bridge. This prevents bridge selection itself\n         * from becoming a capture-latency regression.\n         */\n        if (shortTimestamp <= 0L || ts == shortTimestamp) return false;\n        final long existingBridgeTimestamp = ticket.slot.geometryBridgeSlot.timestamp();\n        if (existingBridgeTimestamp > 0L\n                && Math.abs(ts - shortTimestamp) >= Math.abs(existingBridgeTimestamp - shortTimestamp)) return false;\n        Motion26505LongTicket longTicket = mMotion26505CaptureLongTicket;\n        if (longTicket != null) {\n            long longTimestamp = longTicket.expectedTimestampNs();\n            if (longTimestamp > 0L && ts == longTimestamp) return false;\n        }\n        TotalCaptureResult exact;\n        synchronized (mZslBufferLock) { exact = mZslResultMap.get(ts); }\n        if (exact != null) {\n            Long exp = exact.get(CaptureResult.SENSOR_EXPOSURE_TIME);\n            Integer iso = exact.get(CaptureResult.SENSOR_SENSITIVITY);\n            double baseline = ExposureIndex.time2sec(mMotionUnifiedExposureNs)\n                    * Math.max(mMotionUnifiedIso, 0);\n            if (exp == null || exp <= 0L || iso == null || iso <= 0) return false;\n            double energy = ExposureIndex.time2sec(exp) * iso;\n            if (baseline > 0.0) {\n                double ratio = energy / baseline;\n                if (ratio < 0.72 || ratio > 1.38) return false;\n            }\n        }\n        ImageFrame copy;\n        try {\n            copy = copyMotion26505LongFrame(img, exact);\n        } catch (Throwable t) {\n            Log.w(TAG,"IRIS_26509_BRIDGE_COPY_SKIPPED timestamp="+ts\n                    +" reason="+t.getClass().getSimpleName());\n            return false;\n        }\n        if (copy == null) return false;\n        copy.motionV2FrameRole = ImageFrame.MotionV2FrameRole.NORMAL;\n        copy.motionV2ShortHighlightFrame = false;\n        boolean accepted = ticket.slot.geometryBridgeSlot.offerNearest(copy, shortTimestamp);\n        if (accepted) {\n            Log.d(TAG,"IRIS_26509_BRIDGE_CANDIDATE_STAGED"\n                    +" timestamp="+ts\n                    +" shortTimestampKnown="+(shortTimestamp>0L)\n                    +" exactMetadataNow="+(exact!=null)\n                    +" generation="+ticket.iris26509GenerationId\n                    +" geometryOnly=true pixelContributor=false");\n        }\n        return accepted;\n    }\n\n    private void freezeMotion26509GeometryBridgeMetadata(\n            MotionBatch.ShortHighlightSlot slot) {\n        if (slot == null) return;\n        ImageFrame bridge = slot.geometryBridgeSlot.peek();\n        if (bridge != null && (bridge.motionV2ActualExposureNs <= 0L\n                || bridge.motionV2ActualIso <= 0)) {\n            TotalCaptureResult exact;\n            synchronized (mZslBufferLock) { exact = mZslResultMap.get(bridge.timestamp); }\n            if (exact != null) populateMotion26480FrameMetadata(bridge, exact, false);\n        }\n        bridge = slot.geometryBridgeSlot.peek();\n        slot.geometryBridgeSlot.seal();\n        Log.i(TAG,"IRIS_26509_FROZEN_GEOMETRY_BRIDGE"\n                +" present="+(bridge!=null)\n                +" timestamp="+(bridge==null?0L:bridge.timestamp)\n                +" actualExposureNs="+(bridge==null?0L:bridge.motionV2ActualExposureNs)\n                +" actualIso="+(bridge==null?0:bridge.motionV2ActualIso)\n                +" role="+(bridge==null?"NONE":bridge.motionV2FrameRole)\n                +" immutable=true geometryOnly=true pixelContributor=false shutterWait=false");\n    }\n\n'
EXPOSURE_FIELDS='''    /* IRIS_26509_STABLE_RAW_SIGNAL_NORMAL_EXPOSURE_INTEGRATOR
     * HAL AE remains the live exposure engine. This state is only a slow,
     * hysteretic scene-bias integrator. CaptureRequest SENSOR_* keys are not
     * treated as target sensor values while AE is ON.
     */
    private float mMotion26509NormalStarvationEma = Float.NaN;
    private int mMotion26509AeCandidateDirection = 0;
    private int mMotion26509AeCandidateFrames = 0;
    private static final int MOTION_26509_AE_CONFIRM_FRAMES = 8;
    private static final long MOTION_26509_AE_MIN_UPDATE_MS = 850L;
    private static final float MOTION_26509_AE_MAX_EXTRA_EV = 2.25f;
    private static final float MOTION_26509_AE_SLEW_EV = 0.50f;

'''
EXPOSURE_METHOD='''    /* IRIS_26509_NORMAL_RAW_SIGNAL_EXPOSURE_AUTHORITY
     * Root correction for the dark-Normal / bright-highlight conflict:
     * - HAL AE stays ON (no manual preview shutter ladder).
     * - Short owns clipped-highlight evidence.
     * - Normal exposure receives only a slowly integrated positive AE bias when
     *   the live physical RAW itself is broadly photon-starved.
     * - A wide hysteresis band holds the current bias, avoiding the 26412
     *   brighten/darken feedback oscillation.
     * - CaptureRequest SENSOR_EXPOSURE_TIME/SENSITIVITY are diagnostics only
     *   while CONTROL_AE_MODE is ON; they are never used as an exposure target.
     */
    private void updateMotionV2ExposureAuthority(
            @NonNull TotalCaptureResult result) {
        if (!isZslMode() || mZslCapturing || burst || isProcessing
                || mPreviewRequestBuilder == null || mCaptureSession == null
                || mCameraCharacteristics == null) return;

        Integer aeMode=result.get(CaptureResult.CONTROL_AE_MODE);
        Long actualExposure=result.get(CaptureResult.SENSOR_EXPOSURE_TIME);
        Integer actualIso=result.get(CaptureResult.SENSOR_SENSITIVITY);
        Long ts=result.get(CaptureResult.SENSOR_TIMESTAMP);
        if(aeMode==null || aeMode==CaptureResult.CONTROL_AE_MODE_OFF
                || actualExposure==null || actualIso==null || ts==null
                || actualExposure<=0L || actualIso<=0) return;

        android.util.Range<Integer> range=mCameraCharacteristics.get(
                CameraCharacteristics.CONTROL_AE_COMPENSATION_RANGE);
        android.util.Rational step=mCameraCharacteristics.get(
                CameraCharacteristics.CONTROL_AE_COMPENSATION_STEP);
        if(range==null || step==null || range.getUpper()<=range.getLower()
                || step.floatValue()<=0.0f) return;

        Integer current=mPreviewRequestBuilder.get(
                CaptureRequest.CONTROL_AE_EXPOSURE_COMPENSATION);
        if(!mMotionV2AeBaseReady){
            mMotionV2AeBaseSteps=current!=null?current:0;
            mMotionV2AeBaseSteps=Math.max(range.getLower(),Math.min(range.getUpper(),mMotionV2AeBaseSteps));
            mMotionV2AeAppliedSteps=current!=null?current:mMotionV2AeBaseSteps;
            mMotionV2AeBaseReady=true;
        }

        long age=Math.abs(ts-mMotion26380RawSignalTimestampNs);
        boolean fresh=age<=180_000_000L && mMotion26380RawSampleCount>=64
                && !Float.isNaN(mMotion26380RawFloorFraction)
                && !Float.isNaN(mMotion26380RawShadowFraction)
                && !Float.isNaN(mMotion26380RawHighlightFraction)
                && !Float.isNaN(mMotion26380RawMeanSignal);
        if(!fresh) return;

        float floorNeed=motion26368Clamp01((mMotion26380RawFloorFraction-0.12f)/(0.58f-0.12f));
        float shadowNeed=motion26368Clamp01((mMotion26380RawShadowFraction-0.28f)/(0.78f-0.28f));
        float meanNeed=1.0f-motion26368Clamp01((mMotion26380RawMeanSignal-0.035f)/(0.18f-0.035f));
        float broadStarvation=Math.max(floorNeed,0.82f*shadowNeed)*(0.30f+0.70f*meanNeed);
        if(Float.isNaN(mMotion26509NormalStarvationEma)) {
            mMotion26509NormalStarvationEma=broadStarvation;
        } else {
            mMotion26509NormalStarvationEma=0.88f*mMotion26509NormalStarvationEma
                    +0.12f*broadStarvation;
        }

        long highlightAge=ts-mMotion26496RecentHighlightEvidenceTimestampNs;
        boolean shortHighlightAuthorityAvailable=highlightAge>=0L
                && highlightAge<=MOTION_26496_HIGHLIGHT_EVIDENCE_HOLD_NS;
        float broadClip=motion26368Clamp01((mMotion26380RawHighlightFraction-0.025f)/(0.12f-0.025f));
        long shutterCeiling=iris26381MotionOpportunityCeilingNs(result);
        float shutterOpportunity=motion26368Clamp01(
                (shutterCeiling-actualExposure)/(float)Math.max(1L,shutterCeiling));

        /* Hysteretic error, not an absolute target. The existing applied bias is
         * retained while RAW evidence lives in the hold band. That is the key
         * difference from 26412's self-cancelling absolute-bias controller. */
        float highThreshold=0.34f;
        float lowThreshold=0.16f;
        int desiredDirection=0;
        if(mMotion26509NormalStarvationEma>=highThreshold
                && (shortHighlightAuthorityAvailable || broadClip<0.72f)
                && shutterOpportunity>0.08f) {
            desiredDirection=1;
        } else if(mMotion26509NormalStarvationEma<=lowThreshold
                || (!shortHighlightAuthorityAvailable && broadClip>=0.82f)) {
            desiredDirection=-1;
        }

        if(desiredDirection==mMotion26509AeCandidateDirection) {
            mMotion26509AeCandidateFrames++;
        } else {
            mMotion26509AeCandidateDirection=desiredDirection;
            mMotion26509AeCandidateFrames=1;
        }
        if(desiredDirection==0 || mMotion26509AeCandidateFrames<MOTION_26509_AE_CONFIRM_FRAMES) return;

        long now=android.os.SystemClock.elapsedRealtime();
        if(now-mMotionV2AeLastUpdateMs<MOTION_26509_AE_MIN_UPDATE_MS) return;

        int applied=mMotionV2AeAppliedSteps==Integer.MIN_VALUE
                ?mMotionV2AeBaseSteps:mMotionV2AeAppliedSteps;
        int maxExtraSteps=Math.max(0,Math.round(MOTION_26509_AE_MAX_EXTRA_EV/step.floatValue()));
        int slewSteps=Math.max(1,Math.round(MOTION_26509_AE_SLEW_EV/step.floatValue()));
        int minTarget=mMotionV2AeBaseSteps;
        int maxTarget=Math.min(range.getUpper(),mMotionV2AeBaseSteps+maxExtraSteps);
        int target=applied+desiredDirection*slewSteps;
        target=Math.max(minTarget,Math.min(maxTarget,target));
        target=Math.max(range.getLower(),Math.min(range.getUpper(),target));
        if(target==applied) {
            mMotion26509AeCandidateFrames=0;
            return;
        }

        try{
            mPreviewRequestBuilder.set(CaptureRequest.CONTROL_AE_EXPOSURE_COMPENSATION,target);
            mMotionV2AeAppliedSteps=target;
            mMotionV2AeLastUpdateMs=now;
            mMotion26509AeCandidateFrames=0;
            rebuildPreviewBuilder();
            float appliedExtraEv=(target-mMotionV2AeBaseSteps)*step.floatValue();
            Log.i(TAG,"IRIS_26509_NORMAL_EXPOSURE_BIAS"
                    +" actualExposureNs="+actualExposure+" actualIso="+actualIso
                    +" rawFloor="+mMotion26380RawFloorFraction
                    +" rawShadow="+mMotion26380RawShadowFraction
                    +" rawHighlight="+mMotion26380RawHighlightFraction
                    +" rawMean="+mMotion26380RawMeanSignal
                    +" starvation="+broadStarvation
                    +" starvationEma="+mMotion26509NormalStarvationEma
                    +" shortHighlightAuthority="+shortHighlightAuthorityAvailable
                    +" shutterCeilingNs="+shutterCeiling
                    +" shutterOpportunity="+shutterOpportunity
                    +" direction="+desiredDirection
                    +" compensationSteps="+target
                    +" appliedExtraEv="+appliedExtraEv
                    +" halAeRemainsOn=true requestSensorKeysAreNotAeTargets=true");
        }catch(IllegalArgumentException|IllegalStateException e){
            Log.w(TAG,"IRIS_26509 Normal exposure authority skipped: "+e.getClass().getSimpleName());
        }
    }

'''
FLOW_EXPAND_SHADER='#define LAYOUT //\nLAYOUT\nprecision highp float;\nprecision highp image2D;\nuniform highp sampler2D TileFlow;\nlayout(rgba16f,binding=0) uniform highp writeonly image2D OutputFlow;\nuniform ivec2 outputSize;\nuniform int tileSize;\nuniform float interpolationTolerance;\nvec2 fAt(ivec2 p){ivec2 s=textureSize(TileFlow,0);return texelFetch(TileFlow,clamp(p,ivec2(0),s-ivec2(1)),0).xy;}\n/* IRIS_26509_CONTINUOUS_DENSE_FLOW_UNCERTAINTY_OWNER\n * Previous code switched an entire finest-grid tile to one constant base vector when\n * any of four neighbors crossed a hard disagreement threshold. Always reconstruct the\n * bilinear vector field instead. W now carries continuous normalized disagreement;\n * MGC consumes that uncertainty so geometry risk reduces evidence instead of creating\n * 8x8-packed / ~16x16-RAW displacement blocks. Z retains the native local variation.\n */\nvoid main(){\n ivec2 p=ivec2(gl_GlobalInvocationID.xy);if(any(greaterThanEqual(p,outputSize)))return;\n int ts=max(tileSize,1);ivec2 gs=textureSize(TileFlow,0);\n ivec2 tile=clamp(p/ts,ivec2(0),gs-ivec2(1));ivec2 off=p-tile*ts;\n bool left=off.x<=ts/2,top=off.y<=ts/2;ivec2 t00=ivec2(left?tile.x-1:tile.x,top?tile.y-1:tile.y);\n vec2 f00=fAt(t00),f10=fAt(t00+ivec2(1,0)),f01=fAt(t00+ivec2(0,1)),f11=fAt(t00+ivec2(1,1));\n float ux=float(p.x)/float(ts)-(float(t00.x)+0.5);float uy=float(p.y)/float(ts)-(float(t00.y)+0.5);\n vec2 outF=mix(mix(f00,f10,ux),mix(f01,f11,ux),uy);\n float th=max(float(ts)*interpolationTolerance,1.0e-6);\n float disagreement=max(max(max(abs(f00.x-outF.x),abs(f00.y-outF.y)),max(abs(f10.x-outF.x),abs(f10.y-outF.y))),max(max(abs(f01.x-outF.x),abs(f01.y-outF.y)),max(abs(f11.x-outF.x),abs(f11.y-outF.y))));\n float uncertainty=clamp(disagreement/th,0.0,1.0);\n vec2 mn=vec2(3.4e38),mx=vec2(-3.4e38);for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++){vec2 v=fAt(tile+ivec2(x,y));mn=min(mn,v);mx=max(mx,v);}\n float variation=length((mx-mn)/max(vec2(outputSize),vec2(1.0)));\n imageStore(OutputFlow,p,vec4(outF,variation,uncertainty));\n}\n'
SHADOW_SHADER='#define LAYOUT //\nLAYOUT\nprecision highp float;precision highp int;precision highp image2D;\nuniform highp sampler2D mergedCfa;uniform highp sampler2D referenceCfa;uniform highp sampler2D shadowCfa;uniform highp sampler2D flowTexture;uniform highp sampler2D frameSupport;\nlayout(rgba32f,binding=0) uniform highp writeonly image2D outCfa;layout(rgba32f,binding=1) uniform highp writeonly image2D outSemanticWeight;layout(std430,binding=3) buffer ShadowDiagBuf{uint shadowDiag[];};\nuniform ivec2 packedSize;uniform float referenceExposureScale;uniform float shadowToNormalScale;uniform float shadowExposureRatio;uniform float shadowClipThreshold;uniform float minimumFlowConfidence;uniform float deepShadowThreshold;uniform float deepShadowPackCeiling;uniform float minimumShadowSignal;uniform float requiredExposureSupportRatio;uniform float maxShadowBlend;\n/* IRIS_26498_V13_BOUNDED_PRE_SHUTTER_SHADOW_AUX */\n/* IRIS_26509_LONG_RETAINS_ISOLATED_SHADOW_ONLY_OWNER */\nfloat sum4(vec4 v){return dot(v,vec4(1.0));}float max4(vec4 v){return max(max(v.x,v.y),max(v.z,v.w));}vec4 shadowSafe(vec4 v){return vec4(1.0)-step(vec4(shadowClipThreshold),v);}vec4 phaseSafeShadow(vec2 packedCenter){vec2 p=packedCenter-vec2(0.5);ivec2 lo=ivec2(floor(p));vec2 f=fract(p);ivec2 hi=packedSize-ivec2(1);ivec2 p00=clamp(lo,ivec2(0),hi),p10=clamp(lo+ivec2(1,0),ivec2(0),hi),p01=clamp(lo+ivec2(0,1),ivec2(0),hi),p11=clamp(lo+ivec2(1,1),ivec2(0),hi);vec4 a=texelFetch(shadowCfa,p00,0),b=texelFetch(shadowCfa,p10,0),c=texelFetch(shadowCfa,p01,0),d=texelFetch(shadowCfa,p11,0);return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);}\nbool validateReferenceOwnedCorrespondence(ivec2 p,vec2 source,out float meanErr,out float support){float err=0.0;support=0.0;ivec2 hi=packedSize-ivec2(1);for(int oy=-2;oy<=2;++oy)for(int ox=-2;ox<=2;++ox){if(max(abs(ox),abs(oy))!=2)continue;ivec2 q=p+ivec2(ox,oy);if(any(lessThan(q,ivec2(0)))||any(greaterThan(q,hi)))continue;vec2 qs=source+vec2(float(ox),float(oy));if(qs.x<0.0||qs.y<0.0||qs.x>=float(packedSize.x)||qs.y>=float(packedSize.y))continue;vec4 refSensor=texelFetch(referenceCfa,q,0)/max(referenceExposureScale,1.0e-6);vec4 sh=phaseSafeShadow(qs),shEq=sh*shadowToNormalScale;vec4 mask=(vec4(1.0)-step(vec4(0.85),refSensor))*shadowSafe(sh)*step(vec4(minimumShadowSignal),refSensor);float n=sum4(mask);if(n<1.5)continue;vec4 rel=abs(refSensor-shEq)/max(refSensor,vec4(0.025));err+=dot(rel,mask);support+=n;}meanErr=support>0.0?err/support:1.0e20;return support>=12.0&&meanErr<=0.10;}\nfloat phaseSupport(ivec2 p,int phase){ivec2 rawP=p*2+ivec2(phase&1,(phase>>1)&1);return max(texelFetch(frameSupport,rawP,0).r,1.0);}\nvoid main(){ivec2 p=ivec2(gl_GlobalInvocationID.xy);if(any(greaterThanEqual(p,packedSize)))return;vec4 merged=texelFetch(mergedCfa,p,0),ref=texelFetch(referenceCfa,p,0);vec4 mergedSensor=merged/max(referenceExposureScale,1.0e-6),refSensor=ref/max(referenceExposureScale,1.0e-6);if(max4(mergedSensor)>=deepShadowPackCeiling||max4(refSensor)>=deepShadowPackCeiling){imageStore(outCfa,p,merged);imageStore(outSemanticWeight,p,vec4(0.0));return;}vec2 uv=(vec2(p)+vec2(0.5))/vec2(packedSize);vec4 fs=texture(flowTexture,uv);float flowConfidence=(1.0-clamp(fs.w,0.0,1.0))*exp(-80.0*max(fs.z,0.0));vec2 source=vec2(p)+vec2(0.5)+fs.xy;if(source.x<0.0||source.y<0.0||source.x>=float(packedSize.x)||source.y>=float(packedSize.y)){atomicAdd(shadowDiag[6],1u);imageStore(outCfa,p,merged);imageStore(outSemanticWeight,p,vec4(0.0));return;}if(flowConfidence<minimumFlowConfidence){atomicAdd(shadowDiag[3],1u);imageStore(outCfa,p,merged);imageStore(outSemanticWeight,p,vec4(0.0));return;}float corrErr,corrSupport;if(!validateReferenceOwnedCorrespondence(p,source,corrErr,corrSupport)){atomicAdd(shadowDiag[7],1u);imageStore(outCfa,p,merged);imageStore(outSemanticWeight,p,vec4(0.0));return;}atomicAdd(shadowDiag[2],1u);vec4 sh=phaseSafeShadow(source),shEqSensor=sh*shadowToNormalScale,shEq=shEqSensor*referenceExposureScale,outv=merged;bool any=false;vec4 semanticPhaseWeight=vec4(0.0);float corrConf=1.0-smoothstep(0.06,0.10,corrErr);for(int phase=0;phase<4;++phase){if(mergedSensor[phase]>=deepShadowThreshold||refSensor[phase]>=deepShadowPackCeiling)continue;atomicAdd(shadowDiag[0],1u);if(mergedSensor[phase]<minimumShadowSignal||refSensor[phase]<minimumShadowSignal||shEqSensor[phase]<minimumShadowSignal)continue;atomicAdd(shadowDiag[1],1u);if(sh[phase]>=shadowClipThreshold){atomicAdd(shadowDiag[4],1u);continue;}float radiometric=abs(refSensor[phase]-shEqSensor[phase])/max(refSensor[phase],0.020);if(radiometric>0.22){atomicAdd(shadowDiag[8],1u);continue;}float sup=phaseSupport(p,phase);if(sup<=1.25)atomicAdd(shadowDiag[10],1u);else if(sup<=4.5)atomicAdd(shadowDiag[11],1u);else atomicAdd(shadowDiag[12],1u);float requiredRatio=max(1.50,requiredExposureSupportRatio*sup);if(shadowExposureRatio<requiredRatio){atomicAdd(shadowDiag[9],1u);continue;}float benefit=smoothstep(requiredRatio,min(4.0,requiredRatio+0.75),shadowExposureRatio);float blend=clamp(maxShadowBlend*corrConf*max(benefit,0.25),0.0,maxShadowBlend);outv[phase]=mix(merged[phase],shEq[phase],blend);semanticPhaseWeight[phase]=blend;atomicAdd(shadowDiag[5],1u);atomicAdd(shadowDiag[16+phase],1u);if(mergedSensor[phase]<deepShadowThreshold)atomicAdd(shadowDiag[20],1u);else if(mergedSensor[phase]<deepShadowPackCeiling)atomicAdd(shadowDiag[21],1u);else atomicAdd(shadowDiag[22],1u);any=true;}if(any)atomicAdd(shadowDiag[13],1u);imageStore(outCfa,p,max(outv,vec4(0.0)));imageStore(outSemanticWeight,p,semanticPhaseWeight);}\n'
