 block='''        /* IRIS_26509_ASYNC_JPEGR_OUTPUT_OWNER\n         * Motion image math is complete and the Bitmap/Gainmap are immutable here.\n         * Move 4:4:4 JPEG_R + EXIF + deferred DNG I/O to the existing serialized\n         * output executor, close the pipeline, then release capture immediately.\n         */\n        if(cameraMode==CameraMode.MOTION){\n            final Path iris26509ImagePath=imageFile;\n            final Bitmap iris26509Bitmap=img;\n            final ParseExif.ExifData iris26509Exif=exifData;\n            final ByteBuffer iris26509DngBytes=iris26480DeferredDng;\n            final Path iris26509DngPath=dngFile;\n            final Parameters iris26509DngParams=processingParameters;\n            iris26480DeferredDng=null;\n            final long iris26509QueuedNs=System.nanoTime();\n            MOTION_26480_OUTPUT_EXECUTOR.execute(()->{Integer oldPriority=null;boolean iris26509Saved=false;try{
                int tid=android.os.Process.myTid();oldPriority=android.os.Process.getThreadPriority(tid);
                android.os.Process.setThreadPriority(tid,android.os.Process.THREAD_PRIORITY_BACKGROUND);
                iris26509Saved=ImageSaver.Util.saveBitmapAsJPGMotionV2(iris26509ImagePath,iris26509Bitmap,ImageSaver.JPG_QUALITY,iris26509Exif);
                processingEventsListener.notifyImageSavedStatus(iris26509Saved,iris26509ImagePath);
                if(iris26509DngBytes!=null){iris26509DngBytes.position(0);boolean dngSaved=ImageSaver.Util.saveStackedRaw(iris26509DngPath,iris26509DngBytes,iris26509DngParams);processingEventsListener.notifyImageSavedStatus(dngSaved,iris26509DngPath);}
                Log.i(TAG,"IRIS_26509_ASYNC_JPEGR_OUTPUT_COMPLETE saved="+iris26509Saved+" queuedToSavedMs="+((System.nanoTime()-iris26509QueuedNs)/1000000L));
            }catch(Exception e){
                Log.e(TAG,"IRIS_26509_ASYNC_JPEGR_OUTPUT_FAILED "+Log.getStackTraceString(e));
                try{processingEventsListener.notifyImageSavedStatus(false,iris26509ImagePath);}catch(Throwable ignored){}
            }finally{
                /* IRIS_26509_ASYNC_BITMAP_LIFETIME_OWNER: 26507 recycles only after successful encode. */
                if(iris26509Bitmap!=null&&!iris26509Bitmap.isRecycled())try{iris26509Bitmap.recycle();}catch(Throwable ignored){}
                if(iris26509DngBytes!=null)try{Allocator.free(iris26509DngBytes);}catch(Throwable ignored){}
                if(oldPriority!=null)try{android.os.Process.setThreadPriority(android.os.Process.myTid(),oldPriority);}catch(Throwable ignored){}
            }});
            pipeline.close();Allocator.getMemoryCount();\n            Log.i(TAG,"IRIS_26509_CAPTURE_RELEASE_BEFORE_JPEGR_SAVE captureUnlockedAfterImmutableOutputTransfer=true");\n            callback.onFinished();return;\n        }\n'''
 return one(src,anchor,anchor+block,'async Motion JPEG_R output')

